def lang_of(code):
    code = (code or "en").lower()[:2]
    return code if code in LANGS else "en"


def t(key, lang="en", **kw):
    row = T[key]
    s = row[LANGS.index(lang_of(lang))]
    return s.format(**kw) if kw and isinstance(s, str) else s


def num(x, lang="en", dec=0):
    if x is None:
        return "–"
    s = ("{:,.%df}" % dec).format(x)
    if lang_of(lang) in ("de", "es", "pt"):
        s = s.replace(",", "\x00").replace(".", ",").replace("\x00", ".")
    return s


def pct(x, lang="en", signed=True, dec=0):
    if x is None:
        return "–"
    s = num(abs(x), lang, dec) + " %" if lang_of(lang) in ("de", "es", "pt") else num(abs(x), lang, dec) + "%"
    if not signed:
        return s
    return ("+" if x > 0 else "−" if x < 0 else "±") + s


def mult(x, lang="en"):
    return "–" if x is None else num(x, lang, 1) + "×"


def fmt_type(code, lang="en"):
    key = "fmt_" + (code or "UNKNOWN")
    return t(key if key in T else "fmt_UNKNOWN", lang)
